def kth_smallest_copy(values, k):
    if k < 0 or k >= len(values):
        return None
    result = values.copy()
    lo = 0
    hi = len(result)
    while lo < hi:
        bounds = partition_three(result, lo, hi)
        if k < bounds["lt"]:
            hi = bounds["lt"]
        elif k >= bounds["gt"]:
            lo = bounds["gt"]
        else:
            return result[k]
