def partition_trace(values, lo, hi):
    pivot = values[hi - 1]
    boundary = lo
    steps = []
    for scan in range(lo, hi - 1):
        if values[scan] < pivot:
            swap(values, boundary, scan)
            boundary = boundary + 1
        steps.append([scan, boundary, values.copy()])
    swap(values, boundary, hi - 1)
    return {"pivot": boundary, "steps": steps}

