def quick_three_depth_range(values, lo, hi, depth, stats):
    if depth > stats["depth"]:
        stats["depth"] = depth
    while hi - lo > 1:
        bounds = partition_three(values, lo, hi)
        stats["partitions"] = stats["partitions"] + 1
        lt = bounds["lt"]
        gt = bounds["gt"]
        if lt - lo < hi - gt:
            if lt - lo > 1:
                quick_three_depth_range(values, lo, lt, depth + 1, stats)
            lo = gt
